SELECT tent_id, usr_id, usr_nm, usr_pwd, usr_eml, act_flg, cre_dt, cre_usr_id, upd_dt, upd_usr_id, first_name, last_name, email_verified FROM sso_user
UPPER(usr_nm) LIKE UPPER('%' || #{search} || '%') OR UPPER(usr_id) LIKE UPPER('%' || #{search} || '%') OR UPPER(usr_eml) LIKE UPPER('%' || #{search} || '%') OR UPPER(first_name) LIKE UPPER('%' || #{search} || '%') OR UPPER(last_name) LIKE UPPER('%' || #{search} || '%')
ORDER BY tent_id, usr_nm LIMIT #{maxResults} OFFSET #{firstResult}
